  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "A materially improved general regime: a higher cap and longer notice period"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "a lower de minimis, and a **first-dollar basket** once the threshold is exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "A materially improved general regime: a higher cap and longer notice period"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "A separate **fundamental warranty regime** covering at least title, ownership, authority and capacity"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve claims for fraud and other liabilities that cannot lawfully be excluded; do not allow non-reliance language to undermine them."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject deemed disclosure of public records and anything merely discoverable."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the broad Buyer-knowledge exclusion"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "an express condition precedent requiring a valid, unconditional written consent—or one on terms acceptable to the Buyer"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "**Simultaneous repayment from the Seller’s proceeds at Completion**, with releases delivered then"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "explicit allocation of the bonuses and applicable on-costs to the Seller."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the specific indemnity to cover losses, claims and remediation arising from unpaid amounts, failure of transfer or competing rights"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Negotiate a specific indemnity for losses and reasonable investigation, response and remediation costs arising from the incident"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Restrict non-ordinary renewals between signing and Completion without Buyer consent."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "reject blanket disclosure, discoverability and all-claims limitations; establish separate fundamental, tax and specific-indemnity regimes."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Verify the register against corporate records, share issuances and transfers, and check for encumbrances and rights affecting the shares."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Separate, appropriately longer periods and caps for **tax**, and negotiated protection for IP."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

